// Binary Record Inspector — DOM wiring and Worker host.
// All computation runs in the module Worker built from the fixed embedded
// source (js/worker-source.js, generated by scripts/build.mjs). User input
// is only ever inserted with textContent/value; it never becomes markup.

import { Controller, DEFAULT_DRAFT } from './controller.mjs';
import { WORKER_SOURCE } from './worker-source.js';

const PAGE_SIZE = 25;
const REPORT_FILENAME = 'binary-record-inspector-report.json';
const DOWNLOAD_REVOKE_MS = 30000;

const STRINGS = {
  'zh-Hant': {
    statusEmpty: '請輸入或載入範例。',
    statusDirty: '輸入已變更，請重新執行。',
    statusBusy: '處理中…',
    statusSuccess: '完成。',
    statusCancelled: '已取消，可重新執行。',
    summary: (byteCount, fieldCount) => `共 ${byteCount} bytes，${fieldCount} 欄。`,
    pageInfo: (page, pages) => `第 ${page} / ${pages} 頁`,
    fieldHex: '欄位：十六進位 bytes',
    fieldLayout: '欄位：欄位配置',
    rowLabel: (row) => `列：第 ${row} 列`,
    fileTooBig: '檔案超過 4,096 bytes 上限，請改用較小的檔案。',
    fileReadFailed: '無法讀取檔案，請再試一次。',
    errors: {
      SCHEMA: '輸入結構不正確，請重新整理頁面後再試。',
      INPUT_LIMIT: '輸入太長，請縮短後再試。',
      EMPTY: '缺少內容，請輸入後再執行。',
      UNICODE: '輸入含有不成對的 surrogate，請檢查後再試。',
      HEX_FORMAT: '十六進位格式錯誤：每個 token 須為偶數個十六進位字元（0–9、a–f），不支援 0x 前綴或位址。',
      BYTE_LIMIT: 'bytes 總數超過 4,096，請縮短後再試。',
      LAYOUT_FORMAT: '配置格式錯誤：每列須為「標籤 ⇥ 偏移 ⇥ 型別」；標籤以英文字母開頭、最多 24 字元，偏移為 0 或無前導零的 1–4 位數字。',
      DUP_LABEL: '標籤重複：該標籤已使用過。',
      TYPE: '未知的型別，請用 u8、i8 或 u/i + 16/32/64 + le/be。',
      BOUNDS: '超出範圍：該欄位超出 bytes 末端。',
      OUTPUT_LIMIT: '報告超過 2 MB 上限，無法下載。',
      INTERNAL: '發生內部錯誤，請重新執行。',
      WORKER_ERROR: '背景工作失敗，草稿已保留，請重新執行。',
    },
  },
  en: {
    statusEmpty: 'Enter input or load the example.',
    statusDirty: 'Input changed. Run again.',
    statusBusy: 'Working…',
    statusSuccess: 'Done.',
    statusCancelled: 'Cancelled. You can run again.',
    summary: (byteCount, fieldCount) => `${byteCount} bytes, ${fieldCount} fields.`,
    pageInfo: (page, pages) => `Page ${page} of ${pages}`,
    fieldHex: 'Field: Hex bytes',
    fieldLayout: 'Field: Field layout',
    rowLabel: (row) => `Row: ${row}`,
    fileTooBig: 'The file exceeds the 4,096-byte limit. Use a smaller file.',
    fileReadFailed: 'Could not read the file. Please try again.',
    errors: {
      SCHEMA: 'The input structure is invalid. Reload the page and try again.',
      INPUT_LIMIT: 'The input is too long. Shorten it and try again.',
      EMPTY: 'Nothing to read yet. Enter input and run again.',
      UNICODE: 'The input contains an unpaired surrogate. Check it and try again.',
      HEX_FORMAT: 'Hex format error: every token must have an even number of hex digits (0–9, a–f); no 0x prefix or addresses.',
      BYTE_LIMIT: 'The byte total exceeds 4,096. Shorten the input and try again.',
      LAYOUT_FORMAT: 'Layout format error: each row must be “label ⇥ offset ⇥ type”; labels start with a letter and are at most 24 characters, offsets are 0 or a 1–4 digit number without leading zeros.',
      DUP_LABEL: 'Duplicate label: this label is already used.',
      TYPE: 'Unknown type. Use u8, i8, or u/i + 16/32/64 + le/be.',
      BOUNDS: 'Out of bounds: this field runs past the end of the bytes.',
      OUTPUT_LIMIT: 'The report exceeds the 2 MB limit and cannot be downloaded.',
      INTERNAL: 'An internal error occurred. Run again.',
      WORKER_ERROR: 'The background job failed. Your draft is kept; run again.',
    },
  },
};

const lang = document.documentElement.lang === 'en' ? 'en' : 'zh-Hant';
const S = STRINGS[lang];

const $ = (id) => document.getElementById(id);
const hexInput = $('hex-input');
const layoutInput = $('layout-input');
const fileInput = $('file-input');
const fileError = $('file-error');
const form = $('inspector-form');
const runButton = $('run-button');
const exampleButton = $('example-button');
const resetButton = $('reset-button');
const cancelButton = $('cancel-button');
const exampleNotice = $('example-notice');
const statusEl = $('status');
const errorBox = $('error-box');
const resultsSection = $('results');
const summaryEl = $('summary');
const resultsBody = $('results-body');
const paginationEl = $('pagination');
const prevPageButton = $('prev-page');
const nextPageButton = $('next-page');
const pageInfo = $('page-info');
const downloadButton = $('download-button');

let currentPage = 1;
let downloadUrl = null;
let downloadTimer = null;
let focusErrorOnNextRender = false;
let fileGeneration = 0;

const workerUrl = URL.createObjectURL(
  new Blob([WORKER_SOURCE], { type: 'text/javascript' }),
);

const controller = new Controller({
  createWorker: () => new Worker(workerUrl, { type: 'module' }),
});

function revokeDownload() {
  if (downloadTimer !== null) {
    clearTimeout(downloadTimer);
    downloadTimer = null;
  }
  if (downloadUrl !== null) {
    URL.revokeObjectURL(downloadUrl);
    downloadUrl = null;
  }
}

function errorMessage(error) {
  const lines = [S.errors[error.code] || S.errors.INTERNAL];
  if (error.field === 'hex') lines.push(S.fieldHex);
  else if (error.field === 'layout') lines.push(S.fieldLayout);
  if (error.row !== null && error.row !== undefined) {
    lines.push(S.rowLabel(error.row));
  }
  return lines;
}

function renderResults() {
  const result = controller.result;
  if (!result) {
    resultsSection.hidden = true;
    return;
  }
  resultsSection.hidden = false;
  summaryEl.textContent = S.summary(result.byteCount, result.fields.length);
  const pages = Math.max(1, Math.ceil(result.fields.length / PAGE_SIZE));
  if (currentPage > pages) currentPage = pages;
  const start = (currentPage - 1) * PAGE_SIZE;
  const pageFields = result.fields.slice(start, start + PAGE_SIZE);
  resultsBody.textContent = '';
  for (const field of pageFields) {
    const row = document.createElement('tr');
    const labelCell = document.createElement('td');
    labelCell.className = 'mono';
    labelCell.textContent = field.label;
    const offsetCell = document.createElement('td');
    offsetCell.className = 'mono';
    offsetCell.textContent = String(field.offset);
    const typeCell = document.createElement('td');
    typeCell.className = 'mono';
    typeCell.textContent = field.type;
    const hexCell = document.createElement('td');
    hexCell.className = 'mono';
    hexCell.textContent = field.hex;
    const valueCell = document.createElement('td');
    valueCell.className = 'mono';
    valueCell.textContent = field.value;
    row.append(labelCell, offsetCell, typeCell, hexCell, valueCell);
    resultsBody.append(row);
  }
  if (pages > 1) {
    paginationEl.hidden = false;
    pageInfo.textContent = S.pageInfo(currentPage, pages);
    prevPageButton.disabled = currentPage <= 1;
    nextPageButton.disabled = currentPage >= pages;
  } else {
    paginationEl.hidden = true;
  }
}

function render() {
  const state = controller.state;
  statusEl.dataset.state = state;
  statusEl.setAttribute('aria-busy', state === 'busy' ? 'true' : 'false');
  cancelButton.hidden = state !== 'busy';
  runButton.disabled = state === 'busy';
  exampleButton.disabled = state === 'busy';
  resetButton.disabled = state === 'busy';
  fileInput.disabled = state === 'busy';

  if (state === 'success') {
    statusEl.textContent = S.statusSuccess;
    errorBox.hidden = true;
    errorBox.textContent = '';
    hexInput.removeAttribute('aria-invalid');
    layoutInput.removeAttribute('aria-invalid');
    currentPage = 1;
    renderResults();
  } else if (state === 'error') {
    statusEl.textContent = controller.error
      ? errorMessage(controller.error)[0]
      : S.errors.INTERNAL;
    errorBox.textContent = '';
    for (const line of errorMessage(controller.error || { code: 'INTERNAL' })) {
      const p = document.createElement('p');
      p.textContent = line;
      errorBox.append(p);
    }
    errorBox.hidden = false;
    if (controller.error && controller.error.field === 'hex') {
      hexInput.setAttribute('aria-invalid', 'true');
    } else {
      hexInput.removeAttribute('aria-invalid');
    }
    if (controller.error && controller.error.field === 'layout') {
      layoutInput.setAttribute('aria-invalid', 'true');
    } else {
      layoutInput.removeAttribute('aria-invalid');
    }
    revokeDownload();
    resultsSection.hidden = true;
    if (focusErrorOnNextRender) {
      focusErrorOnNextRender = false;
      if (controller.error && controller.error.field === 'layout') {
        layoutInput.focus();
      } else {
        hexInput.focus();
      }
    }
  } else {
    if (state === 'empty') statusEl.textContent = S.statusEmpty;
    else if (state === 'dirty') statusEl.textContent = S.statusDirty;
    else if (state === 'busy') statusEl.textContent = S.statusBusy;
    else if (state === 'cancelled') statusEl.textContent = S.statusCancelled;
    errorBox.hidden = true;
    errorBox.textContent = '';
    hexInput.removeAttribute('aria-invalid');
    layoutInput.removeAttribute('aria-invalid');
    revokeDownload();
    resultsSection.hidden = true;
  }
}

controller.onchange = render;

function readDraft() {
  return { hex: hexInput.value, layout: layoutInput.value };
}

hexInput.addEventListener('input', () => {
  exampleNotice.hidden = true;
  controller.setDraft(readDraft());
});
layoutInput.addEventListener('input', () => {
  exampleNotice.hidden = true;
  controller.setDraft(readDraft());
});

form.addEventListener('submit', (event) => {
  event.preventDefault();
  focusErrorOnNextRender = true;
  controller.run();
});

exampleButton.addEventListener('click', () => {
  controller.loadExample();
  const draft = controller.draft;
  hexInput.value = draft.hex;
  layoutInput.value = draft.layout;
  exampleNotice.hidden = false;
  fileError.textContent = '';
});

resetButton.addEventListener('click', () => {
  controller.reset();
  hexInput.value = DEFAULT_DRAFT.hex;
  layoutInput.value = DEFAULT_DRAFT.layout;
  fileInput.value = '';
  fileError.textContent = '';
  exampleNotice.hidden = true;
  hexInput.focus();
});

cancelButton.addEventListener('click', () => {
  controller.cancel();
});

prevPageButton.addEventListener('click', () => {
  if (currentPage > 1) {
    currentPage -= 1;
    renderResults();
  }
});

nextPageButton.addEventListener('click', () => {
  const result = controller.result;
  if (!result) return;
  const pages = Math.max(1, Math.ceil(result.fields.length / PAGE_SIZE));
  if (currentPage < pages) {
    currentPage += 1;
    renderResults();
  }
});

downloadButton.addEventListener('click', () => {
  const text = controller.reportText;
  if (text === null) return;
  revokeDownload();
  const blob = new Blob([text], { type: 'application/json;charset=utf-8' });
  downloadUrl = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = downloadUrl;
  anchor.download = REPORT_FILENAME;
  document.body.append(anchor);
  anchor.click();
  anchor.remove();
  downloadTimer = setTimeout(revokeDownload, DOWNLOAD_REVOKE_MS);
});

fileInput.addEventListener('change', () => {
  const file = fileInput.files && fileInput.files[0];
  if (!file) return;
  fileError.textContent = '';
  const generation = (fileGeneration += 1);
  file
    .arrayBuffer()
    .then((buffer) => {
      // A later file selection, cancel, or reset discards this late result.
      if (generation !== fileGeneration) return;
      if (buffer.byteLength > 4096) {
        fileError.textContent = S.fileTooBig;
        return;
      }
      const bytes = new Uint8Array(buffer);
      const parts = [];
      for (const byte of bytes) {
        parts.push(byte.toString(16).padStart(2, '0'));
      }
      hexInput.value = parts.join(' ');
      exampleNotice.hidden = true;
      controller.setDraft(readDraft());
    })
    .catch(() => {
      if (generation !== fileGeneration) return;
      fileError.textContent = S.fileReadFailed;
    });
});

// Leaving the page discards the draft; a bfcache return resets the tool.
window.addEventListener('pagehide', () => {
  fileGeneration += 1;
  controller.reset();
  URL.revokeObjectURL(workerUrl);
});

window.addEventListener('pageshow', (event) => {
  if (event.persisted) {
    controller.reset();
    hexInput.value = DEFAULT_DRAFT.hex;
    layoutInput.value = DEFAULT_DRAFT.layout;
    fileInput.value = '';
    fileError.textContent = '';
    exampleNotice.hidden = true;
    render();
  }
});

render();
